/**
 * Minimal end-to-end smoke for the DeepSeek direct provider.
 *
 * Prereqs:
 *   1. `npm install`
 *   2. `npm run token:refresh:headed`   (one-time sign-in via Playwright)
 *      — writes DEEPSEEK_USER_TOKEN to .env
 *   3. `npm run example`
 *
 * What it does:
 *   - Creates a DeepSeek chat_session_id
 *   - Sends one prompt with streaming chunks → prints to stdout as they arrive
 *   - Prints final stats (latency, token-like char count, finishReason)
 *
 * Notes:
 *   - We read DEEPSEEK_USER_TOKEN from process.env. Either export it in
 *     your shell, or load a .env file (e.g. `node --env-file=.env ...`).
 *     For `tsx`, the `--env-file` flag works the same way.
 */
import { deepseek } from "../src/index";

async function main(): Promise<void> {
  const token = process.env.DEEPSEEK_USER_TOKEN;
  if (!token) {
    console.error("Missing DEEPSEEK_USER_TOKEN. Run: npm run token:refresh:headed");
    process.exitCode = 1;
    return;
  }

  console.log("→ creating session...");
  const sessionId = await deepseek.createSession(token);
  console.log(`  session: ${sessionId}`);

  const prompt = process.argv[2] ?? "اشرح لي ما هو DeepSeek في ثلاث جمل قصيرة.";
  console.log(`→ prompt: ${prompt}\n`);

  process.stdout.write("← ");
  const result = await deepseek.chat({
    token,
    sessionId,
    prompt,
    thinkingEnabled: false,
    searchEnabled: false,
    onChunk: (piece) => process.stdout.write(piece),
  });
  process.stdout.write("\n\n");

  console.log("─".repeat(60));
  console.log(`finishReason : ${result.finishReason}`);
  console.log(`continuations: ${result.continuations}`);
  console.log(`chars        : ${result.text.length}`);
  console.log(`latency      : ${result.totalLatencyMs} ms`);
  console.log(`turns        :`, result.turns);
}

main().catch((err) => {
  console.error("FAILED:", err?.message ?? err);
  if (err?.stack) console.error(err.stack);
  process.exitCode = 1;
});
